scenario.en:
render(<input maxLength={5} onChange={(e) => setQ(e.target.value)} />);

// Test A
fireEvent.change(input, { target: { value: "abcdefgh" } });
expect(input).toHaveValue("abcdefgh");

// Test B
const user = userEvent.setup();
await user.type(input, "abcdefgh");
